// Module kmsg contains generated Kafka protocol request and response types.
//
// Every file except this one is generated by generate/gen_v.py from the
// franz-go protocol definitions — do not hand-edit generated files.
//
// Usage pattern:
//
//	mut req := kmsg.MetadataRequest{
//		version: 12
//		topics:  [kmsg.MetadataRequestTopic{
//			topic: 'my-topic'
//		}]
//	}
//	mut w := kbin.Writer{}
//	req.write_to(mut w)
//	// ... send w.buf, receive resp_bytes ...
//	mut resp := kmsg.MetadataResponse{
//		version: req.version
//	}
//	mut r := kbin.Reader{
//		src: resp_bytes
//	}
//	resp.read_from(mut r)!
module kmsg

import kbin

// UnknownTag is a flexible-version tagged field this client does not know.
// Unknown tags read from the wire are preserved and re-encoded verbatim, so
// decode/encode round-trips are lossless even across protocol additions.
pub struct UnknownTag {
pub mut:
	tag  u32
	data []u8
}

// Request is implemented by all generated *Request types. The version
// field is mutable through the interface so the client can negotiate it.
pub interface Request {
	key() i16
	max_version() i16
	is_flexible() bool
	write_to(mut w Writer)
mut:
	version i16
	read_from(mut r Reader) !
}

// Response is implemented by all generated *Response types. A response's
// version must be set to the version of the request that produced it before
// calling read_from.
pub interface Response {
	key() i16
	max_version() i16
	is_flexible() bool
	write_to(mut w Writer)
mut:
	version i16
	read_from(mut r Reader) !
}

// write_unknown_tags appends preserved unknown tags to w. Generated code
// calls this at the end of each flexible tag section.
pub fn write_unknown_tags(mut w Writer, tags []UnknownTag) {
	for t in tags {
		w.write_uvarint(t.tag)
		w.write_uvarint(u32(t.data.len))
		w.buf << t.data
	}
}
